#include "hip_api.h"
#include <vector>
#include <fstream>
#include <chrono>
#include <cstdio>
using namespace hip_probe;
int main(){try{Api a;a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");Handle m{},f[3]{},s{};a.Check(a.LoadModule(&m,"gfx1201.hsaco"),"module");a.Check(a.hipModuleGetFunction(&f[0],m,"expand16"),"f16");a.Check(a.hipModuleGetFunction(&f[1],m,"expand32"),"f32");a.Check(a.hipModuleGetFunction(&f[2],m,"expand32n32"),"f32n32");a.Check(a.hipStreamCreate(&s),"stream");
auto upload=[&](const char*n){std::ifstream file(n,std::ios::binary|std::ios::ate);if(!file)throw std::runtime_error(n);std::vector<char>b(size_t(file.tellg()));file.seekg(0);file.read(b.data(),b.size());void*p{};a.Check(a.hipMalloc(&p,b.size()),"alloc");a.Check(a.hipMemcpy(p,b.data(),b.size(),1),"upload");return p;};unsigned M=26624;void*x=upload("input.fp8"),*w=upload("weight.fp8"),*o{};a.Check(a.hipMalloc(&o,size_t(M)*512),"out");void*args[]={&x,&w,&o,&M};auto run=[&](int method){a.Check(a.hipModuleLaunchKernel(f[method],M/(method?32:16)*(method==2?16:8),1,1,32,1,1,0,s,args,nullptr),"launch");};std::vector<char>ref(size_t(M)*512),got(ref.size());run(0);a.Check(a.hipStreamSynchronize(s),"ref sync");a.Check(a.hipMemcpy(ref.data(),o,ref.size(),2),"ref read");run(1);a.Check(a.hipStreamSynchronize(s),"check sync");a.Check(a.hipMemcpy(got.data(),o,got.size(),2),"check read");if(got!=ref)throw std::runtime_error("M32 differs");FILE*csv=fopen("timing.csv","wb");fprintf(csv,"candidate,slot,method,ms\n");
for(int r: {1,2,2,1})for(int slot=0;slot<4;slot++){int method=(slot==1||slot==2)?r:0;for(int j=0;j<10000;j++)run(method);a.Check(a.hipStreamSynchronize(s),"warm");auto t=std::chrono::steady_clock::now();for(int j=0;j<20000;j++)run(method);a.Check(a.hipStreamSynchronize(s),"done");double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count()/20000;fprintf(csv,"%d,%d,%d,%.9f\n",r,slot,method,ms);printf("candidate%d slot%d method%d %.6fms\n",r,slot,method,ms);fflush(stdout);a.Check(a.hipMemcpy(got.data(),o,got.size(),2),"verify");if(got!=ref)throw std::runtime_error("Batch output changed");}fclose(csv);puts("PASS all outputs byte-exact");a.hipFree(x);a.hipFree(w);a.hipFree(o);a.hipStreamDestroy(s);a.hipModuleUnload(m);return 0;}catch(const std::exception&e){puts(e.what());return 1;}}
